import sys
from collections import namedtuple

Interval = namedtuple('Interval', 'start end')

def overlappedInterval(intervals):
    if not intervals:
        return []

    intervals.sort(key=lambda x: x.start)
    merged = [intervals[0]]

    for current in intervals[1:]:
        last_merged = merged[-1]
        if current.start <= last_merged.end:
            merged[-1] = Interval(last_merged.start, max(last_merged.end, current.end))
        else:
            merged.append(current)

    return merged

def main():
    import sys
    input = sys.stdin.read().strip()
    intervals = [Interval(*map(int, pair.split(','))) for pair in input.split()]
    result = overlappedInterval(intervals)
    print(" ".join(f"{{{interval.start},{interval.end}}}" for interval in result))

if __name__ == "__main__":
    main()
